const ROUTE_LABELS=new Map([['#/materials','素材库'],['#/today','今日待看'],['#/brief','每日选材晨报'],['#/accounts','对标账号'],['#/observations','观察记录']]);
const CONTENT_LABELS={product_showcase:'产品纯展示',product_selling:'产品带货',product_talking:'产品口播',creator_selling:'达人带货',ugc_review:'UGC 使用体验',comparison:'测评/对比',tutorial:'教程演示',story:'剧情植入',unboxing:'开箱素材',live_clip:'直播切片',brand_ad:'品牌广告',unknown:'暂不确定'};
export function escapeHtml(value){return String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));}
export function qualityLabel(item){const size=item.width&&item.height?`${item.width}×${item.height}`:'尺寸未知';if(item.kind==='cover')return `封面 · ${size}`;if(item.kind==='clip')return `${item.duration_seconds||8} 秒短片 · ${size}`;const kind=item.kind==='hd'?'高清文件':item.kind==='full'?'完整文件':'轻量视频';return `${kind} · ${size}${item.duration_seconds?` · ${item.duration_seconds} 秒`:''}`;}
function mediaFrom(manifest,id){return manifest.media instanceof Map?manifest.media.get(id):manifest.media?.[id];}
function metric(value){return value===null||value===undefined?'未知':Number(value).toLocaleString('zh-CN');}
function nav(route){return [...ROUTE_LABELS].map(([href,label])=>`<a href="${href}"${href===route?' aria-current="page"':''}>${label}</a>`).join('');}
function badges(values=[]){return values.map(value=>`<span class="badge">${escapeHtml(value)}</span>`).join('');}
function fieldValue(filters,name){return escapeHtml(filters?.[name]??'');}
function option(value,label,current){return `<option value="${value}"${current===value?' selected':''}>${label}</option>`;}
function paginationControls(pagination){if(!pagination||pagination.totalPages<=1)return '';return `<nav class="pagination" aria-label="分页"><button type="button" data-page="${pagination.page-1}"${pagination.page<=1?' disabled':''}>上一页</button><span>第 ${pagination.page}/${pagination.totalPages} 页</span><button type="button" data-page="${pagination.page+1}"${pagination.page>=pagination.totalPages?' disabled':''}>下一页</button></nav>`;}
function summaryCard(record){const m=record.metrics;return `<article class="summary-card"><p class="eyebrow">${escapeHtml(record.report_day)} · ${record.status==='complete'?'完整':'部分完成'}</p><h2>晨报数据概况</h2><div class="summary-metrics"><span>账号成功 <strong>${metric(m.accounts_success)}</strong></span><span>账号受阻 <strong>${metric(m.accounts_blocked)}</strong></span><span>收录作品 <strong>${metric(m.posts_sampled)}</strong></span><span>延后处理 <strong>${metric(m.posts_deferred)}</strong></span></div><p class="muted">发布时间 ${escapeHtml(record.published_at||'未知')}</p></article>`;}
function card(record,manifest){if(record.kind==='daily_summary')return summaryCard(record);const media=(record.media_ids||[]).map(id=>mediaFrom(manifest,id)).filter(Boolean);const cover=media.find(item=>item.kind==='cover');const playable=media.find(item=>item.kind!=='cover');const title=record.description||record.display_name||record.account_display||record.account||record.username||'未命名记录';return `<article class="card"><div class="media-frame">${cover?.url?`<img src="${escapeHtml(cover.url)}" alt="作品封面" loading="lazy">`:'<span>暂无可用封面</span>'}</div><div class="card-body"><p class="account">${escapeHtml(record.account_display||record.display_name||record.account||record.username||'')}</p><h2>${escapeHtml(title)}</h2><div>${badges(record.categories)}${badges(record.products)}</div>${record.content_type?`<p class="muted">${escapeHtml(CONTENT_LABELS[record.content_type]||record.content_type)}</p>`:''}<p class="metrics">播放 ${metric(record.metrics?.views)} · 点赞 ${metric(record.metrics?.likes)}</p><p class="muted">${escapeHtml(record.published_at?.slice(0,10)||'日期未知')}</p>${playable?.url?`<button class="media-button" data-media-url="${escapeHtml(playable.url)}" data-media-label="${escapeHtml(qualityLabel(playable))}">播放或下载 · ${escapeHtml(qualityLabel(playable))}</button>`:'<button disabled>暂无视频</button>'}</div></article>`;}
export function renderClosed(){return '<main class="closed"><div><span class="brand-mark">R</span><h1>网站暂时关闭</h1><p>请联系网站负责人确认恢复时间。</p></div></main>';}
export function renderPage({route,manifest,records,totalRecords=records.length,pagination={page:1,totalPages:1},filters={},closed=false}){if(closed)return renderClosed();const title=ROUTE_LABELS.get(route)||'素材库',pool=filters.pool||'company';return `<header class="topbar"><a class="brand" href="#/materials"><span class="brand-mark">R</span><span><strong>素材雷达</strong><small>公开只读</small></span></a><nav aria-label="主要页面">${nav(route)}</nav></header><main class="page"><section class="notice"><strong>公开只读版本</strong><p>数据来自本机工作台最近一次成功同步，可查看、播放和下载已有文件。</p></section><section class="page-heading"><div><p class="eyebrow">CONTENT INTELLIGENCE</p><h1>${title}</h1><p class="muted">版本 ${escapeHtml(manifest.version)} · ${escapeHtml(manifest.generated_at)}</p></div><div class="pool-tabs"><button data-pool="company" aria-pressed="${pool==='company'}">公司对标</button><button data-pool="market" aria-pressed="${pool==='market'}">市场对标</button></div></section><form id="filters" class="filters"><label>搜索<input name="query" type="search" maxlength="100" value="${fieldValue(filters,'query')}"></label><label>类目<input name="category" maxlength="120" value="${fieldValue(filters,'category')}"></label><label>产品<input name="product" maxlength="120" value="${fieldValue(filters,'product')}"></label><label>开始日期<input name="date_from" type="date" value="${fieldValue(filters,'date_from')}"></label><label>结束日期<input name="date_to" type="date" value="${fieldValue(filters,'date_to')}"></label><label>内容类型<select name="content_type">${option('','全部',filters.content_type||'')}${Object.entries(CONTENT_LABELS).map(([value,label])=>option(value,label,filters.content_type)).join('')}</select></label><button class="primary">筛选</button></form><p id="result-status" class="result-status">共 ${totalRecords} 条 · 第 ${pagination.page}/${pagination.totalPages} 页</p><section id="records" class="record-grid">${records.length?records.map(item=>card(item,manifest)).join(''):'<div class="empty">当前条件没有记录。</div>'}</section>${paginationControls(pagination)}</main><dialog id="media-dialog"><div class="dialog-head"><strong id="media-label">媒体预览</strong><button data-dialog-close aria-label="关闭预览">关闭</button></div><video controls playsinline preload="metadata"></video><a class="download" target="_blank" rel="noopener noreferrer">下载文件</a></dialog>`;}
